"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Percent, RefreshCw, Loader2, AlertTriangle, Trash2 } from "lucide-react";
import { useToast } from "@/app/components/Toast";
import { AnimatedModal } from "@/components/ui/modal";

export interface PromotionItem {
  id: number;
  code: string;
  title: string;
  description?: string | null;
  discount_type: "PERCENTAGE" | "FIXED";
  discount_value: number;
  min_order_amount: number;
  usage_limit?: number | null;
  used_count: number;
  starts_at: string;
  expires_at?: string | null;
  is_active: boolean;
}

function formatDiscount(p: PromotionItem) {
  return p.discount_type === "PERCENTAGE"
    ? `${Number(p.discount_value)}%`
    : `₱${Number(p.discount_value).toFixed(2)}`;
}

function formatDate(value?: string | null) {
  if (!value) return "—";
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString();
}

function statusOf(p: PromotionItem): { label: string; className: string } {
  const now = Date.now();
  if (!p.is_active)
    return { label: "Inactive", className: "bg-muted text-muted-foreground border border-border" };
  if (p.expires_at && new Date(p.expires_at).getTime() < now)
    return { label: "Expired", className: "bg-rose-500/20 text-rose-600 dark:text-rose-400 border border-rose-500/30" };
  if (new Date(p.starts_at).getTime() > now)
    return { label: "Scheduled", className: "bg-sky-500/20 text-sky-600 dark:text-sky-300 border border-sky-500/30" };
  return { label: "Active", className: "bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30" };
}

export function AdminPromotionsView() {
  const toast = useToast();
  const [promotions, setPromotions] = useState<PromotionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingDelete, setPendingDelete] = useState<PromotionItem | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchPromotions = useCallback(async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/promotions", { cache: "no-store", credentials: "include" });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false) {
        throw new Error(data.error || `HTTP ${res.status}`);
      }
      setPromotions(data.promotions || []);
    } catch (err: any) {
      setError(err?.message || "Failed to load promotions.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchPromotions();
  }, [fetchPromotions]);

  const confirmDelete = async () => {
    if (!pendingDelete) return;
    setDeleting(true);
    try {
      const res = await fetch(`/api/admin/promotions?id=${pendingDelete.id}`, {
        method: "DELETE",
        credentials: "include",
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false) {
        throw new Error(data.error || "Failed to delete promotion");
      }
      if (data.deleted === false) {
        throw new Error("Promotion was not deleted.");
      }
      toast.success(`Promotion ${pendingDelete.code} deleted.`);
      setPendingDelete(null);
      fetchPromotions(true);
    } catch (err: any) {
      toast.error(err?.message || "Failed to delete promotion");
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="space-y-6 w-full">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-5 rounded-2xl bg-card border border-border">
        <div>
          <h1 className="text-xl sm:text-2xl font-semibold text-foreground font-sans">Promotions</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            Review discount codes and remove ones you no longer want to offer.
          </p>
        </div>
        <button
          onClick={() => fetchPromotions(true)}
          disabled={refreshing || loading}
          className="px-3 py-2 rounded-xl bg-secondary hover:bg-secondary/80 border border-border text-secondary-foreground hover:text-foreground text-xs font-mono transition-colors flex items-center gap-1.5 cursor-pointer disabled:opacity-50 self-start sm:self-auto"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${refreshing ? "animate-spin" : ""}`} />
          <span>Refresh</span>
        </button>
      </div>

      <div className="rounded-2xl border border-border bg-card overflow-hidden shadow-sm">
        {loading ? (
          <div className="p-16 flex flex-col items-center justify-center space-y-3 text-muted-foreground">
            <Loader2 className="w-6 h-6 animate-spin" />
            <div className="text-xs font-mono">Loading promotions...</div>
          </div>
