            <AlertTriangle className="w-8 h-8 mx-auto text-rose-500" />
            <div className="text-sm font-semibold text-foreground">{error}</div>
            <button
              onClick={() => fetchPromotions()}
              className="px-3 py-1.5 rounded-xl bg-secondary hover:bg-secondary/80 text-xs font-mono border border-border cursor-pointer"
            >
              Retry
            </button>
          </div>
        ) : promotions.length === 0 ? (
          <div className="p-16 text-center space-y-3 text-muted-foreground">
            <Percent className="w-8 h-8 mx-auto opacity-60" />
            <div className="text-sm font-medium text-foreground">No promotions yet</div>
