"use client";

import React, { useState, useEffect, useCallback } from "react";
import { Percent, RefreshCw, Loader2, AlertTriangle, Trash2 } from "lucide-react";
import { useToast } from "@/app/components/Toast";
import { AnimatedModal } from "@/components/ui/modal";

export interface PromotionItem {
  id: number;
  code: string;
  title: string;
  description?: string | null;
  discount_type: "PERCENTAGE" | "FIXED";
  discount_value: number;
  min_order_amount: number;
  usage_limit?: number | null;
  used_count: number;
  starts_at: string;
  expires_at?: string | null;
  is_active: boolean;
}

function formatDiscount(p: PromotionItem) {
  return p.discount_type === "PERCENTAGE"
    ? `${Number(p.discount_value)}%`
    : `₱${Number(p.discount_value).toFixed(2)}`;
}

function formatDate(value?: string | null) {
  if (!value) return "—";
  const d = new Date(value);
  return Number.isNaN(d.getTime()) ? "—" : d.toLocaleDateString();
}

function statusOf(p: PromotionItem): { label: string; className: string } {
  const now = Date.now();
  if (!p.is_active)
    return { label: "Inactive", className: "bg-muted text-muted-foreground border border-border" };
  if (p.expires_at && new Date(p.expires_at).getTime() < now)
    return { label: "Expired", className: "bg-rose-500/20 text-rose-600 dark:text-rose-400 border border-rose-500/30" };
  if (new Date(p.starts_at).getTime() > now)
    return { label: "Scheduled", className: "bg-sky-500/20 text-sky-600 dark:text-sky-300 border border-sky-500/30" };
  return { label: "Active", className: "bg-emerald-500/20 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30" };
}

export function AdminPromotionsView() {
  const toast = useToast();
  const [promotions, setPromotions] = useState<PromotionItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [pendingDelete, setPendingDelete] = useState<PromotionItem | null>(null);
  const [deleting, setDeleting] = useState(false);

  const fetchPromotions = useCallback(async (isRefresh = false) => {
    if (isRefresh) setRefreshing(true);
    else setLoading(true);
    setError(null);
    try {
      const res = await fetch("/api/admin/promotions", { cache: "no-store", credentials: "include" });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false) {
        throw new Error(data.error || `HTTP ${res.status}`);
      }
      setPromotions(data.promotions || []);
    } catch (err: any) {
      setError(err?.message || "Failed to load promotions.");
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  }, []);

  useEffect(() => {
    fetchPromotions();
  }, [fetchPromotions]);

  const confirmDelete = async () => {
    if (!pendingDelete) return;
    setDeleting(true);
    try {
      const res = await fetch(`/api/admin/promotions?id=${pendingDelete.id}`, {
        method: "DELETE",
        credentials: "include",
      });
      const data = await res.json().catch(() => ({}));
      if (!res.ok || data.success === false) {
        throw new Error(data.error || "Failed to delete promotion");
      }
      if (data.deleted === false) {
        throw new Error("Promotion was not deleted.");
      }
      toast.success(`Promotion ${pendingDelete.code} deleted.`);
      setPendingDelete(null);
      fetchPromotions(true);
    } catch (err: any) {
      toast.error(err?.message || "Failed to delete promotion");
    } finally {
      setDeleting(false);
    }
  };

  return (
    <div className="space-y-6 w-full">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 p-5 rounded-2xl bg-card border border-border">
        <div>
          <h1 className="text-xl sm:text-2xl font-semibold text-foreground font-sans">Promotions</h1>
          <p className="text-sm text-muted-foreground mt-0.5">
            Review discount codes and remove ones you no longer want to offer.
          </p>
        </div>
        <button
          onClick={() => fetchPromotions(true)}
          disabled={refreshing || loading}
          className="px-3 py-2 rounded-xl bg-secondary hover:bg-secondary/80 border border-border text-secondary-foreground hover:text-foreground text-xs font-mono transition-colors flex items-center gap-1.5 cursor-pointer disabled:opacity-50 self-start sm:self-auto"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${refreshing ? "animate-spin" : ""}`} />
          <span>Refresh</span>
        </button>
      </div>

      <div className="rounded-2xl border border-border bg-card overflow-hidden shadow-sm">
        {loading ? (
          <div className="p-16 flex flex-col items-center justify-center space-y-3 text-muted-foreground">
            <Loader2 className="w-6 h-6 animate-spin" />
            <div className="text-xs font-mono">Loading promotions...</div>
          </div>
        ) : error ? (
          <div className="p-12 text-center space-y-3">
            <AlertTriangle className="w-8 h-8 mx-auto text-rose-500" />
            <div className="text-sm font-semibold text-foreground">{error}</div>
            <button
              onClick={() => fetchPromotions()}
              className="px-3 py-1.5 rounded-xl bg-secondary hover:bg-secondary/80 text-xs font-mono border border-border cursor-pointer"
            >
              Retry
            </button>
          </div>
        ) : promotions.length === 0 ? (
          <div className="p-16 text-center space-y-3 text-muted-foreground">
            <Percent className="w-8 h-8 mx-auto opacity-60" />
            <div className="text-sm font-medium text-foreground">No promotions yet</div>
            <p className="text-xs">Promotions you create will appear here.</p>
          </div>
        ) : (
          <div className="overflow-x-auto scrollbar-none">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b border-border bg-muted/40 text-[11px] font-mono uppercase text-muted-foreground tracking-wider">
                  <th className="py-3 px-4 sm:px-6">Promotion</th>
                  <th className="py-3 px-4">Discount</th>
                  <th className="py-3 px-4">Min. order</th>
                  <th className="py-3 px-4">Used</th>
                  <th className="py-3 px-4">Valid</th>
                  <th className="py-3 px-4">Status</th>
                  <th className="py-3 px-4 sm:px-6 text-right">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border text-xs font-sans">
                {promotions.map((p) => {
                  const status = statusOf(p);
                  return (
                    <tr key={p.id} className="hover:bg-muted/30 transition-colors">
                      <td className="py-3.5 px-4 sm:px-6">
                        <div className="font-mono font-semibold text-foreground">{p.code}</div>
                        <div className="text-[11px] text-muted-foreground mt-0.5">{p.title}</div>
                      </td>
                      <td className="py-3.5 px-4 font-mono font-medium text-foreground">{formatDiscount(p)}</td>
                      <td className="py-3.5 px-4 font-mono text-muted-foreground">
                        ₱{Number(p.min_order_amount || 0).toFixed(2)}
                      </td>
                      <td className="py-3.5 px-4 font-mono text-muted-foreground">
                        {p.used_count}
                        {p.usage_limit ? ` / ${p.usage_limit}` : ""}
                      </td>
                      <td className="py-3.5 px-4 font-mono text-muted-foreground">
                        {formatDate(p.starts_at)} – {p.expires_at ? formatDate(p.expires_at) : "No expiry"}
                      </td>
                      <td className="py-3.5 px-4">
                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-mono uppercase font-semibold ${status.className}`}>
                          {status.label}
                        </span>
                      </td>
                      <td className="py-3.5 px-4 sm:px-6 text-right">
                        <button
                          type="button"
                          onClick={() => setPendingDelete(p)}
                          aria-label={`Delete promotion ${p.code}`}
                          className="inline-flex items-center gap-1 px-2.5 py-1 rounded-lg bg-rose-500/10 hover:bg-rose-500/20 text-rose-600 dark:text-rose-400 border border-rose-500/20 text-xs font-semibold transition-colors cursor-pointer"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                          Delete
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <AnimatedModal
        isOpen={!!pendingDelete}
        onClose={() => !deleting && setPendingDelete(null)}
        title="Delete promotion?"
        description={pendingDelete ? `"${pendingDelete.code}" will be permanently removed. This can't be undone.` : ""}
      >
        <div className="flex justify-end gap-2 p-4">
          <button
            type="button"
            onClick={() => setPendingDelete(null)}
            disabled={deleting}
            className="px-3 py-2 rounded-xl bg-secondary hover:bg-secondary/80 border border-border text-xs font-semibold cursor-pointer disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={confirmDelete}
            disabled={deleting}
            className="px-3 py-2 rounded-xl bg-rose-600 hover:bg-rose-500 text-white text-xs font-semibold cursor-pointer disabled:opacity-50 flex items-center gap-1.5"
          >
            {deleting && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
            Delete promotion
          </button>
        </div>
      </AnimatedModal>
    </div>
  );
}

export default AdminPromotionsView;

